>Tambahkan assignment</button></form></section><section class="card"><h2>Akses Fitur</h2><p class="muted">Override tidak pernah menggantikan permission atau scope backend.</p><form method="post" action="{{ route('admin.system.users.features.update',$managedUser) }}">@csrf @method('PUT')@foreach($features->groupBy('module') as $module => $moduleFeatures)<h3>{{ $module }}</h3>@foreach($moduleFeatures as $feature)@php($state=$managedUser->featureOverrides->firstWhere('feature_id',$feature->id)?->state ?? 'INHERIT')@php($result=$resolver->resolve($managedUser,$feature->code))<div class="feature"><div><strong>{{ $feature->name }}</strong><br><small class="muted">{{ $feature->code }} · Efektif: {{ $result['effective_enabled'] ? 'diizinkan' : 'ditolak ('.$result['denial_reason'].')' }}</small></div><select name="features[{{ $feature->id }}]" aria-label="Override {{ $feature->name }}"><option value="INHERIT" @selected($state==='INHERIT')>INHERIT</option><option value="ENABLED" @selected($state==='ENABLED')>ENABLED</option><option value="DISABLED" @selected($state==='DISABLED')>DISABLED</option></select></div>@endforeach @endforeach<button class="button" type="submit">Simpan akses fitur</button></form></section><section class="card"><h2>Preferensi</h2><form method="post" action="{{ route('admin.system.users.preferences.update',$managedUser) }}">@csrf @method('PUT')@php($prefs=$managedUser->preferences->keyBy('preference_key')->map(fn($p)=>$p->preference_value['value'] ?? null))<div class="grid"><div class="field"><label for="default_landing_page">Halaman awal</label><select id="default_landing_page" name="default_landing_page"><option value="academic.dashboard" @selected($prefs->get('default_landing_page')==='academic.dashboard')>Dashboard akademik</option><option value="admin.academic.dashboard" @selected($prefs->get('default_landing_page')==='admin.academic.dashboard')>Dashboard admin</option></select></div><div class="field"><label for="table_page_size">Jumlah baris tabel</label><select id="table_page_size" name="table_page_size"><option value="10" @selected((string)$prefs->get('table_page_size')==='10')>10</option><option value="25" @selected((string)$prefs->get('table_page_size')==='25' || !$prefs->has('table_page_size'))>25</option><option value="50" @selected((string)$prefs->get('table_page_size')==='50')>50</option></select></div></div><label><input type="checkbox" name="sidebar_compact" value="1" @checked($prefs->get('sidebar_compact') === true)> Sidebar ringkas</label><br><label><input type="checkbox" name="show_help_text" value="1" @checked($prefs->get('show_help_text') !== false)> Tampilkan bantuan</label><p><button class="button" type="submit">Simpan preferensi</button></p></form></section></div></main></div></body></html>
